SELECT item.workshop_id,item.file_uid,item.file_author,item.name AS level_name,COALESCE((SELECT metadata.format FROM public.level_metadata metadata WHERE metadata.id_level=item.id_level ORDER BY metadata.id LIMIT 1),0)::integer AS format FROM public.track_tournament tournament JOIN public.level level ON level.id=tournament.id_level AND level.publicly_visible=true JOIN public.level_item item ON item.id_level=level.id AND item.deleted=false AND item.publicly_visible=true WHERE tournament.id=$1 ORDER BY item.updated_at DESC,item.id DESC
